bool Player::withdrawItem(uint16_t itemId, uint32_t amount) {
	const auto it = stashItems.find(itemId);
	if (it != stashItems.end()) {
		if (it->second > amount) {
			stashItems[itemId] -= amount;
		} else if (it->second == amount) {
			stashItems.erase(itemId);
		} else {
			return false;
		}
		return true;
	}
	return false;
}

