	if (states.empty()) {
		return nullptr;
	}

	const auto &top = states.back();

bool Player::withdrawItem(uint16_t itemId, uint32_t amount) {
	auto it = stashItems.find(itemId);
	if (it != stashItems.end()) {
		if (it->second > amount) {
			it->second -= amount;
			return true;
		}

		if (it->second == amount) {
			stashItems.erase(it);
			return true;
		}
	}
	return false;
}

