}

bool Player::removeItemOfType(uint16_t itemId, uint32_t amount, int32_t subType, bool ignoreEquipped /* = false*/) const {
	if (amount == 0) {
		return true;
	}

	std::vector<std::shared_ptr<Item>> itemList;

	uint32_t count = 0;
	for (int32_t i = CONST_SLOT_FIRST; i <= CONST_SLOT_LAST; i++) {
		const auto &item = inventory[i];
		if (!item) {
			continue;
		}

		if (!ignoreEquipped && item->getID() == itemId) {
			const uint32_t itemCount = Item::countByType(item, subType);
			if (itemCount == 0) {
				continue;
			}

			itemList.emplace_back(item);

			count += itemCount;
			if (count >= amount) {
				g_game().internalRemoveItems(itemList, amount, Item::items[itemId].stackable);
				return true;
			}
		} else if (const auto &container = item->getContainer()) {
			for (ContainerIterator it = container->iterator(); it.hasNext(); it.advance()) {
				const auto &containerItem = *it;
				if (containerItem->getID() == itemId) {
					const uint32_t itemCount = Item::countByType(containerItem, subType);
					if (itemCount == 0) {
						continue;
					}

					itemList.emplace_back(containerItem);

					count += itemCount;
					const auto stackable = Item::items[itemId].stackable;
					// If the amount of items in the backpack is equal to or greater than the amount
					// It will remove items and stop the iteration
					if (count >= amount) {
						g_game().internalRemoveItems(itemList, amount, stackable);
						return true;
					}
				}
			}
		}
	}

void ContainerIterator::advance() {
	if (states.empty()) {
		return;
	}

	auto &top = states.back();
	const auto &container = top.container.lock();
	if (!container) {
		// Container has been deleted
		states.pop_back();
		return;
	}

	if (top.index >= container->itemlist.size()) {
		states.pop_back();
		return;
	}

	const auto &currentItem = container->itemlist[top.index];
	if (currentItem) {
		const auto &subContainer = currentItem->getContainer();
		if (subContainer && !subContainer->itemlist.empty()) {
			size_t newDepth = top.depth + 1;
			if (newDepth <= maxTraversalDepth) {
				if (visitedContainers.find(subContainer) == visitedContainers.end()) {
					states.emplace_back(subContainer, 0, newDepth);
					visitedContainers.insert(subContainer);
				} else {
					if (!m_cycleDetected) {
						g_logger().trace("[{}] Cycle detected in container: {}", __FUNCTION__, subContainer->getName());
						m_cycleDetected = true;
					}
				}
			} else {
				if (!m_maxDepthReached) {
					g_logger().trace("[{}] Maximum iteration depth reached", __FUNCTION__);
					m_maxDepthReached = true;
				}
			}
		}
	}

	++top.index;
}

std::shared_ptr<Item> ContainerIterator::operator*() const {
	if (states.empty()) {
		return nullptr;
	}

	const auto &top = states.back();

bool Player::withdrawItem(uint16_t itemId, uint32_t amount) {
	auto it = stashItems.find(itemId);
	if (it != stashItems.end()) {
		if (it->second > amount) {
			it->second -= amount;
			return true;
		}

		if (it->second == amount) {
			stashItems.erase(it);
			return true;
		}
	}
	return false;
}

